SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS `{{prefix}}users` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `username` VARCHAR(80) NOT NULL, `password_hash` VARCHAR(255) NOT NULL, `role` VARCHAR(30) NOT NULL, `display_name` VARCHAR(160) NOT NULL, `created_at` DATETIME NOT NULL, `last_login_at` DATETIME NULL, PRIMARY KEY (`id`), UNIQUE KEY `uq_users_username` (`username`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `{{prefix}}demo_workspaces` (`id` CHAR(32) NOT NULL, `demo_date` DATE NOT NULL, `is_template` TINYINT(1) NOT NULL DEFAULT 0, `created_at` DATETIME NOT NULL, `expires_at` DATETIME NOT NULL, PRIMARY KEY (`id`), KEY `idx_workspace_expiry` (`expires_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `{{prefix}}patients` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `workspace_id` CHAR(32) NOT NULL, `code` VARCHAR(8) NOT NULL, `full_name` VARCHAR(180) NOT NULL, `birth_date` DATE NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uq_patient_code` (`workspace_id`,`code`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `{{prefix}}studies` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `workspace_id` CHAR(32) NOT NULL, `patient_id` BIGINT UNSIGNED NOT NULL, `study_uid` VARCHAR(40) NOT NULL, `study_type` VARCHAR(100) NOT NULL, `study_date` DATE NOT NULL, `conclusion` TEXT NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uq_study_uid` (`workspace_id`,`study_uid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `{{prefix}}facilities` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `workspace_id` CHAR(32) NOT NULL, `name` VARCHAR(160) NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `{{prefix}}services` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `workspace_id` CHAR(32) NOT NULL, `name` VARCHAR(160) NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `{{prefix}}specialists` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `workspace_id` CHAR(32) NOT NULL, `full_name` VARCHAR(180) NOT NULL, `service_id` BIGINT UNSIGNED NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `{{prefix}}routes` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `workspace_id` CHAR(32) NOT NULL, `patient_id` BIGINT UNSIGNED NOT NULL, `study_id` BIGINT UNSIGNED NOT NULL, `status` VARCHAR(24) NOT NULL, `assigned_to` VARCHAR(160) NULL, `attention_reason` VARCHAR(40) NULL, `due_date` DATE NOT NULL, `return_reason` VARCHAR(255) NULL, `created_at` DATETIME NOT NULL, `completed_at` DATETIME NULL, PRIMARY KEY (`id`), KEY `idx_routes_workspace` (`workspace_id`,`status`,`attention_reason`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `{{prefix}}route_steps` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `workspace_id` CHAR(32) NOT NULL, `route_id` BIGINT UNSIGNED NOT NULL, `sequence_no` SMALLINT UNSIGNED NOT NULL, `title` VARCHAR(255) NOT NULL, `service_id` BIGINT UNSIGNED NULL, `status` VARCHAR(24) NOT NULL, `required` TINYINT(1) NOT NULL DEFAULT 1, `confirmation_required` TINYINT(1) NOT NULL DEFAULT 0, `document_label` VARCHAR(255) NULL, `due_date` DATE NOT NULL, `completed_at` DATETIME NULL, PRIMARY KEY (`id`), KEY `idx_steps_route` (`workspace_id`,`route_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `{{prefix}}schedule_slots` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `workspace_id` CHAR(32) NOT NULL, `service_id` BIGINT UNSIGNED NOT NULL, `specialist_id` BIGINT UNSIGNED NOT NULL, `facility_id` BIGINT UNSIGNED NOT NULL, `starts_at` DATETIME NOT NULL, `status` VARCHAR(20) NOT NULL DEFAULT 'free', PRIMARY KEY (`id`), UNIQUE KEY `uq_specialist_time` (`workspace_id`,`specialist_id`,`starts_at`), KEY `idx_slots_workspace` (`workspace_id`,`starts_at`,`status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `{{prefix}}appointments` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `workspace_id` CHAR(32) NOT NULL, `route_step_id` BIGINT UNSIGNED NOT NULL, `slot_id` BIGINT UNSIGNED NOT NULL, `status` VARCHAR(24) NOT NULL, `reason` VARCHAR(255) NULL, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`id`), KEY `idx_appointments_slot` (`workspace_id`,`slot_id`,`status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `{{prefix}}comments` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `workspace_id` CHAR(32) NOT NULL, `route_id` BIGINT UNSIGNED NOT NULL, `body` TEXT NOT NULL, `author` VARCHAR(160) NOT NULL, `created_at` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `{{prefix}}event_log` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `workspace_id` CHAR(32) NOT NULL, `route_id` BIGINT UNSIGNED NULL, `event_type` VARCHAR(40) NOT NULL, `message` VARCHAR(500) NOT NULL, `author` VARCHAR(160) NOT NULL, `created_at` DATETIME NOT NULL, PRIMARY KEY (`id`), KEY `idx_events_workspace` (`workspace_id`,`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `{{prefix}}settings` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `workspace_id` CHAR(32) NOT NULL, `setting_key` VARCHAR(100) NOT NULL, `setting_value` TEXT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uq_setting` (`workspace_id`,`setting_key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `{{prefix}}action_keys` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `workspace_id` CHAR(32) NOT NULL, `request_key` VARCHAR(64) NOT NULL, `created_at` DATETIME NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uq_action_key` (`workspace_id`,`request_key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `{{prefix}}login_attempts` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `identity` VARCHAR(180) NOT NULL, `attempted_at` DATETIME NOT NULL, PRIMARY KEY (`id`), KEY `idx_attempt_identity` (`identity`,`attempted_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `{{prefix}}migrations` (`version` VARCHAR(60) NOT NULL, `applied_at` DATETIME NOT NULL, PRIMARY KEY (`version`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
